<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

final class MSRWA_Admin {
	public static function hooks() {
		add_action( 'admin_menu', array( __CLASS__, 'menu' ), 30 );
		add_action( 'admin_init', array( __CLASS__, 'settings' ) );
		add_action( 'admin_enqueue_scripts', array( __CLASS__, 'assets' ) );
	}

	public static function menu() {
		add_menu_page( 'MS Recipes Writer', 'MS Recipes Writer', 'edit_posts', 'ms-recipes-writer-ai', array( __CLASS__, 'page' ), 'dashicons-edit-page', 58 );
		add_submenu_page( 'ms-recipes-writer-ai', 'Créer des Articles/Images', 'Créer des Articles/Images', 'edit_posts', 'ms-recipes-writer-ai', array( __CLASS__, 'page' ) );
		add_submenu_page( 'ms-recipes-writer-ai', 'Statistiques', 'Statistiques', 'edit_posts', 'ms-recipes-writer-ai-stats', array( __CLASS__, 'stats_page' ) );
		add_submenu_page( 'ms-recipes-writer-ai', 'Configuration', 'Configuration', 'manage_options', 'ms-recipes-writer-ai-settings', array( __CLASS__, 'settings_page' ) );
	}

	public static function settings() { register_setting( 'msrwa_settings', MSRWA_Settings::OPTION, array( 'sanitize_callback' => array( 'MSRWA_Settings', 'sanitize' ) ) ); }

	public static function assets( $hook ) {
		if ( false === strpos( $hook, 'ms-recipes-writer-ai' ) ) { return; }
		wp_enqueue_style( 'msrwa-admin', MSRWA_URL . 'assets/admin.css', array(), MSRWA_VERSION );
		wp_enqueue_script( 'msrwa-admin', MSRWA_URL . 'assets/admin.js', array(), MSRWA_VERSION, true );
		wp_localize_script( 'msrwa-admin', 'MSRWA', array( 'api' => esc_url_raw( rest_url( 'msrwa/v1' ) ), 'nonce' => wp_create_nonce( 'wp_rest' ) ) );
	}

	public static function page() {
		if ( ! current_user_can( 'edit_posts' ) ) { wp_die( esc_html__( 'Accès refusé.', 'ms-recipes-writer-ai' ) ); }
		$settings = MSRWA_Settings::get();
		global $wpdb;
		$tables = MSRWA_DB::tables();
		$owner_filter = current_user_can( 'msrwa_view_all' ) || current_user_can( 'manage_options' ) ? '' : $wpdb->prepare( ' WHERE owner_id = %d', get_current_user_id() );
		$recent_batches = $wpdb->get_results( "SELECT id,status,total,completed,created_at,updated_at FROM {$tables['batches']} {$owner_filter} ORDER BY id DESC LIMIT 20", ARRAY_A );
		?>
		<div class="wrap msrwa-wrap msrwa-create-page"><div class="msrwa-page-head"><div><h1>MS Recipes Writer</h1><p class="description">Créez des articles et des images à partir d’un seul brief culinaire.</p></div><a class="button" href="<?php echo esc_url( admin_url( 'admin.php?page=ms-recipes-writer-ai-stats' ) ); ?>">Voir les statistiques</a></div><section class="msrwa-card msrwa-composer"><h2>Créer des Articles/Images</h2><p class="description">Fournissez une recette, un titre ou des instructions. Les images peuvent être ajoutées par URL ou depuis votre ordinateur.</p><form id="msrwa-create-form" enctype="multipart/form-data" data-max-reference-images="<?php echo esc_attr( $settings['max_reference_images'] ); ?>"><label for="msrwa-recipe">Texte ou recette fournie<textarea id="msrwa-recipe" rows="12" maxlength="20000" placeholder="Exemple : Tarte aux pommes... ingrédients, étapes, temps et consignes éditoriales."></textarea></label><div class="msrwa-reference-grid"><label for="msrwa-image-urls">Images de référence — URLs<textarea id="msrwa-image-urls" rows="5" placeholder="Une URL HTTPS par ligne"></textarea><span class="description">Les URLs sont vérifiées puis stockées temporairement hors du document public.</span></label><label for="msrwa-reference-files">Images de référence — depuis l’ordinateur<input type="file" id="msrwa-reference-files" name="reference_files[]" accept="image/jpeg,image/png,image/webp,image/gif" multiple><span id="msrwa-files-help" class="description">Jusqu’à <?php echo esc_html( $settings['max_reference_images'] ); ?> images, taille maximale 10 Mo par fichier.</span></label></div><div class="msrwa-form-actions"><button type="submit" class="button button-primary button-hero" id="msrwa-create">Créer le lot</button><span id="msrwa-message" role="status" aria-live="polite"></span></div></form></section><section class="msrwa-card"><div class="msrwa-section-head"><h2>Lots récents</h2><span class="description">Les détails et contrôles restent disponibles après création.</span></div><div class="msrwa-table-scroll"><table class="widefat striped"><thead><tr><th>ID</th><th>État</th><th>Progression</th><th>Créé</th><th>Mis à jour</th><th>Actions</th></tr></thead><tbody><?php if ( empty( $recent_batches ) ) : ?><tr><td colspan="6">Aucun lot.</td></tr><?php else : foreach ( $recent_batches as $batch ) : ?><tr><td><?php echo esc_html( $batch['id'] ); ?></td><td class="msrwa-batch-status"><?php echo esc_html( $batch['status'] ); ?></td><td><?php echo esc_html( $batch['completed'] . ' / ' . $batch['total'] ); ?></td><td><?php echo esc_html( $batch['created_at'] ); ?></td><td><?php echo esc_html( $batch['updated_at'] ); ?></td><td class="msrwa-actions"><button type="button" class="button msrwa-batch-action" data-action="pause" data-batch-id="<?php echo esc_attr( $batch['id'] ); ?>">Pause</button> <button type="button" class="button msrwa-batch-action" data-action="resume" data-batch-id="<?php echo esc_attr( $batch['id'] ); ?>">Reprendre</button> <button type="button" class="button msrwa-batch-action" data-action="cancel" data-batch-id="<?php echo esc_attr( $batch['id'] ); ?>">Annuler</button></td></tr><?php endforeach; endif; ?></tbody></table></div></section></div>
		<?php
	}

	public static function stats_page() {
		if ( ! current_user_can( 'edit_posts' ) ) { wp_die( esc_html__( 'Accès refusé.', 'ms-recipes-writer-ai' ) ); }
		$owner_id = current_user_can( 'msrwa_view_all' ) || current_user_can( 'manage_options' ) ? 0 : get_current_user_id();
		$range = isset( $_GET['msrwa_range'] ) ? sanitize_key( wp_unslash( $_GET['msrwa_range'] ) ) : '7';
		$range = in_array( $range, array( 'today', '7', '30' ), true ) ? $range : '7';
		$days = 'today' === $range ? 1 : absint( $range );
		$stats = MSRWA_Stats::summary( $days, $owner_id );
		$call_count = array_sum( array_column( $stats['calls'], 'count' ) );
		$completed = isset( $stats['jobs']['completed'] ) ? (int) $stats['jobs']['completed'] : 0;
		$failed = ( isset( $stats['jobs']['failed'] ) ? (int) $stats['jobs']['failed'] : 0 ) + ( isset( $stats['jobs']['needs_review'] ) ? (int) $stats['jobs']['needs_review'] : 0 );
		$from = gmdate( 'Y-m-d', time() - max( 0, $days - 1 ) * DAY_IN_SECONDS );
		$to = gmdate( 'Y-m-d' );
		$export_base = rest_url( 'msrwa/v1/export' );
		?>
		<div class="wrap msrwa-wrap msrwa-stats-page"><div class="msrwa-page-head"><div><h1>Statistiques</h1><p class="description"><?php echo esc_html( $owner_id ? 'Vos résultats, coûts et événements.' : 'Résultats, coûts et événements de tous les éditeurs.' ); ?></p></div><a class="button" href="<?php echo esc_url( admin_url( 'admin.php?page=ms-recipes-writer-ai' ) ); ?>">Créer un article</a></div><nav class="msrwa-range-tabs" aria-label="Période"><a class="<?php echo 'today' === $range ? 'is-active' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'page' => 'ms-recipes-writer-ai-stats', 'msrwa_range' => 'today' ), admin_url( 'admin.php' ) ) ); ?>">Aujourd’hui</a><a class="<?php echo '7' === $range ? 'is-active' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'page' => 'ms-recipes-writer-ai-stats', 'msrwa_range' => '7' ), admin_url( 'admin.php' ) ) ); ?>">7 jours</a><a class="<?php echo '30' === $range ? 'is-active' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'page' => 'ms-recipes-writer-ai-stats', 'msrwa_range' => '30' ), admin_url( 'admin.php' ) ) ); ?>">30 jours</a></nav><section class="msrwa-kpis"><div><span>Jobs</span><strong><?php echo esc_html( $stats['total_jobs'] ); ?></strong></div><div><span>Terminés</span><strong><?php echo esc_html( $completed ); ?></strong></div><div><span>À vérifier / échecs</span><strong><?php echo esc_html( $failed ); ?></strong></div><div><span>Appels</span><strong><?php echo esc_html( $call_count ); ?></strong></div><div><span>Coût estimé</span><strong><?php echo esc_html( number_format_i18n( (float) $stats['estimated_cost_usd'], 4 ) ); ?> $</strong></div></section><section class="msrwa-card"><div class="msrwa-section-head"><div><h2>Appels par fournisseur et modèle</h2><p class="description">Les coûts sont estimés selon le tarif capturé au moment de l’appel ; les réponses incertaines restent identifiées dans le journal.</p></div><div><a class="button" href="<?php echo esc_url( add_query_arg( array( 'dataset' => 'jobs', 'from' => $from, 'to' => $to, 'format' => 'csv' ), $export_base ) ); ?>">Jobs CSV</a> <a class="button" href="<?php echo esc_url( add_query_arg( array( 'dataset' => 'calls', 'from' => $from, 'to' => $to, 'format' => 'csv' ), $export_base ) ); ?>">Appels CSV</a></div></div><div class="msrwa-table-scroll"><table class="widefat striped"><thead><tr><th>Fournisseur</th><th>Modèle</th><th>Étape</th><th>État</th><th>Appels</th><th>Entrée</th><th>Sortie</th><th>Coût estimé</th></tr></thead><tbody><?php if ( empty( $stats['calls'] ) ) : ?><tr><td colspan="8">Aucun appel pour cette période.</td></tr><?php else : foreach ( $stats['calls'] as $call ) : ?><tr><td><?php echo esc_html( $call['provider'] ); ?></td><td><?php echo esc_html( $call['model'] ); ?></td><td><?php echo esc_html( $call['operation'] ); ?></td><td><?php echo esc_html( $call['status'] ); ?></td><td><?php echo esc_html( $call['count'] ); ?></td><td><?php echo esc_html( number_format_i18n( $call['input_tokens'] ) ); ?></td><td><?php echo esc_html( number_format_i18n( $call['output_tokens'] ) ); ?></td><td><?php echo esc_html( number_format_i18n( (float) $call['cost'], 4 ) ); ?> $</td></tr><?php endforeach; endif; ?></tbody></table></div></section></div>
		<?php
	}

	public static function settings_page() {
		if ( ! current_user_can( 'manage_options' ) ) { wp_die( esc_html__( 'Accès refusé.', 'ms-recipes-writer-ai' ) ); }
		$s = MSRWA_Settings::get();
		?><div class="wrap msrwa-wrap"><h1>MS Recipes Writer AI — Réglages</h1><form method="post" action="options.php"><?php settings_fields( 'msrwa_settings' ); ?><div class="msrwa-card"><h2>Mode et limites</h2><label>Mode imposé<select name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[mode]"><option value="automatic" <?php selected( $s['mode'], 'automatic' ); ?>>Automatique — équilibre qualité/coût</option><option value="manual" <?php selected( $s['mode'], 'manual' ); ?>>Manuel — réglages administrateur</option></select></label><div class="msrwa-fields"><label>Lot maximum<input type="number" min="1" max="50" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[max_batch]" value="<?php echo esc_attr( $s['max_batch'] ); ?>"></label><label>Simultané maximum<input type="number" min="1" max="4" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[max_concurrency]" value="<?php echo esc_attr( $s['max_concurrency'] ); ?>"></label><label>Corrections maximum<input type="number" min="0" max="2" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[max_corrections]" value="<?php echo esc_attr( $s['max_corrections'] ); ?>"></label></div></div>
		<div class="msrwa-card"><h2>Fournisseurs</h2><?php foreach ( array( 'openai' => 'OpenAI', 'gemini' => 'Gemini', 'claude' => 'Claude' ) as $key => $label ) : ?><label><?php echo esc_html( $label ); ?> API key<input type="password" autocomplete="new-password" name="<?php echo esc_attr( MSRWA_Settings::OPTION . '[' . $key . '_key]' ); ?>" value="" placeholder="Clé conservée si laissée vide"></label><?php endforeach; ?><p class="description">Les clés ne sont jamais affichées ni écrites dans les journaux. Leur présence seule n’active pas d’appel payant.</p><?php if ( current_user_can( 'manage_options' ) ) : ?><p><button type="button" class="button msrwa-test-provider" data-provider="openai">Tester OpenAI</button> <span id="msrwa-openai-status" role="status"></span></p><p><button type="button" class="button msrwa-test-provider" data-provider="gemini">Tester Gemini</button> <span id="msrwa-gemini-status" role="status"></span></p><p><button type="button" class="button msrwa-test-provider" data-provider="claude">Tester Claude</button> <span id="msrwa-claude-status" role="status"></span></p><?php endif; ?></div>
		<div class="msrwa-card"><h2>Recherche de secours</h2><label>Mode<select name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[research_fallback_provider]"><option value="none" <?php selected( $s['research_fallback_provider'], 'none' ); ?>>Désactivée</option><option value="custom_json" <?php selected( $s['research_fallback_provider'], 'custom_json' ); ?>>Service JSON personnalisé</option></select></label><label>URL HTTPS du service<input type="url" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[research_fallback_url]" value="<?php echo esc_attr( $s['research_fallback_url'] ); ?>" placeholder="https://…"></label><label>Clé du service<input type="password" autocomplete="new-password" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[research_fallback_key]" value="" placeholder="Clé conservée si laissée vide"></label><p class="description">Appelée uniquement après l’échec de la recherche native. Le service doit accepter POST JSON {query,max_results} et retourner results[{url,title,content}]. Les URL privées, HTTP et redirections non sûres sont refusées.</p></div>
		<div class="msrwa-card"><h2>Budgets</h2><label><input type="checkbox" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[allow_paid_tests]" value="1" <?php checked( $s['allow_paid_tests'], 1 ); ?>> Autoriser les appels API payants de test</label><div class="msrwa-fields"><label>Budget de test (USD)<input type="number" min="0" max="1000" step="0.01" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[test_budget_usd]" value="<?php echo esc_attr( $s['test_budget_usd'] ); ?>"></label><label>Par recette (USD)<input type="number" min="0" step="0.01" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[per_recipe_budget_usd]" value="<?php echo esc_attr( $s['per_recipe_budget_usd'] ); ?>"></label><label>Par jour (USD)<input type="number" min="0" step="0.01" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[daily_budget_usd]" value="<?php echo esc_attr( $s['daily_budget_usd'] ); ?>"></label><label>Par mois (USD)<input type="number" min="0" step="0.01" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[monthly_budget_usd]" value="<?php echo esc_attr( $s['monthly_budget_usd'] ); ?>"></label><label>Réserve image incertaine (USD)<input type="number" min="0.01" step="0.01" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[image_reserve_usd]" value="<?php echo esc_attr( $s['image_reserve_usd'] ); ?>"></label><label>Réserve vision (USD)<input type="number" min="0.01" step="0.01" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[vision_reserve_usd]" value="<?php echo esc_attr( $s['vision_reserve_usd'] ); ?>"></label></div><p class="description">Zéro signifie aucune limite additionnelle. Les coûts image et vision restent estimés jusqu’à la réconciliation fournisseur.</p></div>
		<div class="msrwa-card"><h2>Liens internes</h2><label><input type="checkbox" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[internal_links_enabled]" value="1" <?php checked( $s['internal_links_enabled'], 1 ); ?>> Suggérer des liens vers les recettes déjà publiées</label><label>Nombre maximal de liens<input type="number" min="0" max="10" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[internal_links_max]" value="<?php echo esc_attr( $s['internal_links_max'] ); ?>"></label><label>Titre de la section ajoutée si nécessaire<input type="text" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[internal_links_heading]" value="<?php echo esc_attr( $s['internal_links_heading'] ); ?>"></label><p class="description">Les liens sont proposés à l’agent depuis le contenu local publié, puis ajoutés dans l’article si le modèle n’a pas déjà placé les ancres. Aucun domaine externe ne sera accepté.</p></div>
		<div class="msrwa-card"><h2>Mapping des intégrations</h2><p class="description">Les valeurs sont les clés de métadonnées utilisées par le thème et MS Facebook Posts. Seules les clés connues sont acceptées.</p><textarea rows="8" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[integration_mapping_json]"><?php echo esc_textarea( wp_json_encode( $s['integration_mapping'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES ) ); ?></textarea></div>
		<div class="msrwa-card"><h2>Modèles manuels par étape</h2><p class="description">Utilisés uniquement lorsque le mode Manuel est imposé. Les modèles doivent rester stables et compatibles avec l’étape.</p><?php foreach ( array( 'text' => 'Rédaction et structure', 'review' => 'Relecture', 'image' => 'Images', 'search' => 'Recherche' ) as $stage => $label ) : ?><label><?php echo esc_html( $label ); ?><select name="<?php echo esc_attr( MSRWA_Settings::OPTION . '[manual_models][' . $stage . ']' ); ?>"><?php foreach ( MSRWA_Catalog::models() as $provider => $models ) : foreach ( $models as $model_id => $model ) : ?><option value="<?php echo esc_attr( $provider . ':' . $model_id ); ?>" <?php selected( $s['manual_models'][ $stage ], $provider . ':' . $model_id ); ?>><?php echo esc_html( $provider . ' — ' . $model['label'] ); ?></option><?php endforeach; endforeach; ?></select></label><?php endforeach; ?></div>
		<div class="msrwa-card"><h2>Prompts</h2><p class="description">Ces valeurs par défaut servent aux premiers tests et à la première installation. Vous pouvez ensuite les adapter sans modifier le code. Les sorties structurées restent obligatoires.</p><label>Nombre maximal d’images de référence par recette<input type="number" min="0" max="10" name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[max_reference_images]" value="<?php echo esc_attr( $s['max_reference_images'] ); ?>"></label><?php foreach ( array( 'prompt_research' => 'Recherche web', 'prompt_association' => 'Association', 'prompt_reference_vision' => 'Analyse vision des références', 'prompt_recipe' => 'Recette canonique', 'prompt_nutrition' => 'Nutrition estimée', 'prompt_article' => 'Article et métadonnées', 'prompt_seo' => 'SEO', 'prompt_correction' => 'Correction', 'prompt_review' => 'Relecture et correction', 'prompt_image' => 'Image principale', 'prompt_image_review' => 'Contrôle image', 'prompt_facebook_image' => 'Image Facebook' ) as $key => $label ) : ?><label><?php echo esc_html( $label ); ?><textarea rows="6" name="<?php echo esc_attr( MSRWA_Settings::OPTION . '[' . $key . ']' ); ?>"><?php echo esc_textarea( $s[ $key ] ); ?></textarea></label><?php endforeach; ?></div><?php submit_button( 'Enregistrer les réglages' ); ?></form></div><?php
	}
}
